vector<long long> buildW(int a) {
    int off = a*a;
    vector<long long> W(2*a*a+1, 0);
    for (int i = -a; i <= a; ++i) {
        for (int j = -a; j <= a; ++j) {
            int mx = max({0, i, j});
            int mn = min({0, i, j});
            int range = mx - mn;
            long long L = a + 1 - range;
            if (L < 0) L = 0;
            int s = i * j;
