#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

vector<long long> buildW(int a) {
    int off = a * a;
    vector<long long> W(2 * a * a + 1, 0);
    for (int i = -a; i <= a; ++i)
        for (int j = -a; j <= a; ++j) {
            int mx = max({0, i, j}), mn = min({0, i, j});
            long long L = a + 1 - (mx - mn);
            if (L < 0) L = 0;
            W[i * j + off] += L;
        }
    return W;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int mx, my;
    cin >> mx >> my;
    int a = mx, b = my;
    long long N = (long long)(a + 1) * (b + 1);
    long long total = N * (N - 1) * (N - 2) / 6;

    long long Dg = 0;
    for (int dx = -a; dx <= a; ++dx)
        for (int dy = -b; dy <= b; ++dy) {
            if (!dx && !dy) continue;
            int g = std::gcd(abs(dx), abs(dy));
            Dg += (long long)(g - 1) * (a + 1 - abs(dx)) * (b + 1 - abs(dy));
        }
    Dg /= 2;

    auto Wx = buildW(a), Wy = buildW(b);
    int offx = a * a, offy = b * b;

    long long Z = 0;
    for (int s = -a * a; s <= a * a; ++s) {
        int t = -s;
        if (t < -b * b || t > b * b) continue;
        Z += Wx[s + offx] * Wy[t + offy];
    }
    long long right = (Z - (2 * N * N - N)) / 2;

    int mnT = -b * b, mxT = b * b, len = mxT - mnT + 1;
    vector<long long> pref(len + 1, 0);
    for (int i = 0; i < len; ++i) pref[i + 1] = pref[i] + Wy[mnT + i + offy];

    long long oneg = 0;
    for (int s = -a * a; s <= a * a; ++s) {
        long long wx = Wx[s + offx];
        if (!wx) continue;
        int L = -s - 1;
        if (L < mnT) continue;
        if (L > mxT) L = mxT;
        oneg += wx * pref[L - mnT + 1];
    }
    long long Sneg = oneg / 2;

    long long obtuse = Sneg - Dg;
    long long acute = total - right - Sneg;
    cout << acute << '\n' << right << '\n' << obtuse << '\n' << Dg << '\n';
    return 0;
}
